<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();api_rate_limit($user,'devices.list',30,60);$stmt=db()->prepare('SELECT device_id,device_name,platform,os_version,app_version,status,last_active_at,created_at FROM user_devices WHERE user_id=? ORDER BY last_active_at DESC');$stmt->execute([$user['id']]);json_response(true,'Devices retrieved',$stmt->fetchAll());
